 92456), (73509, 311), (85052, 71670), (197423, 74678), (197423, 218049), (87736, 200846), (306644, 808), (227, 501), (200240, 76576), (200486, 310553), (756, 308890), (71558, 87660), (310308, 94262), (445, 82946), (95222, 71842), (78011, 248367), (82587, 124), (500, 502), (69053, 619), (80302, 80306), (153, 148), (462, 77336), (544, 77460), (74805, 216225), (286, 664), (71269, 202677), (201967, 1440), (94309, 94265), (265760, 1125), (205876, 130), (72507, 698), (215453, 205806), (1381, 1476), (260281, 93751), (219014, 75117), (203446, 77936), (217085, 81810), (253787, 243401), (76447, 76439), (193905, 200756), (428, 219), (256836, 141), (1426, 92358), (88642, 216518), (218194, 87082), (502, 500), (502, 310271), (205372, 285), (71958, 95266), (437, 66007), (130, 77395), (130, 205876), (130, 201603), (74690, 290267), (76580, 74691), (74691, 76580), (82684, 75110), (92827, 194371), (256710, 221716), (75879, 1490), (1490, 75879), (289830, 77167), (1139, 69233), (202090, 757), (94655, 65971), (95266, 71958), (75082, 75038), (82897, 202621), (216246, 1125), (310007, 759), (217069, 202183), (310271, 502), (258879, 88443), (69233, 1139), (87705, 92428), (87705, 71003), (71003, 87705), (80306, 80302), (218331, 200435), (929, 205859), (217997, 216339), (194758, 194757), (200304, 200205), (66007, 437), (73915, 142), (442, 428), (219, 428), (92456, 499), (75038, 75082), (696, 76319), (235, 70643), (204221, 216834), (94364, 197103), (664, 286), (193913, 198854), (95380, 300553), (95380, 1529), (216834, 204221), (92358, 1426), (816, 65906) ) AS t(s, d) ), srp_deduped AS ( SELECT -- CAST(DATE_TRUNC('day', DATE_ADD('minute', 330, s."__time")) AS DATE) AS doi, s.mri_session_id, s.route_id, s.rb_user_id, s.user_type, s.os, s.channel, s.src_id, s.dest_id, rm.region, -- CASE -- WHEN date_diff('day', DATE(DATE_ADD('minute', 330, s."__time")), s.doj) = 0 -- AND HOUR(DATE_ADD('minute', 330, s."__time")) >= 17 THEN '0. LMB Same Day' -- WHEN date_diff('day', DATE(DATE_ADD('minute', 330, s."__time")), s.doj) = 0 THEN '0. non-LMB Same Day' -- WHEN date_diff('day', DATE(DATE_ADD('minute', 330, s."__time")), s.doj) = 1 THEN '1. DBD 1' -- WHEN date_diff('day', DATE(DATE_ADD('minute', 330, s."__time")), s.doj) = 2 THEN '2. DBD 2' -- WHEN date_diff('day', DATE(DATE_ADD('minute', 330, s."__time")), s.doj) > 2 THEN '3. DBD 2+' -- ELSE 'NA' END AS search_day, CASE WHEN s.__time >= TIMESTAMP '2025-08-31 18:30:00' AND s.__time < TIMESTAMP '2025-09-30 18:30:00' THEN 'Sep 2025' WHEN s.__time >= TIMESTAMP '2025-09-30 18:30:00' AND s.__time < TIMESTAMP '2025-10-31 18:30:00' THEN 'Oct 2025' WHEN s.__time >= TIMESTAMP '2025-10-31 18:30:00' AND s.__time < TIMESTAMP '2025-11-30 18:30:00' THEN 'Nov 2025' WHEN s.__time >= TIMESTAMP '2025-11-30 18:30:00' AND s.__time < TIMESTAMP '2025-12-31 18:30:00' THEN 'Dec 2025' WHEN s.__time >= TIMESTAMP '2025-12-31 18:30:00' AND s.__time < TIMESTAMP '2026-01-31 18:30:00' THEN 'Jan 2026' WHEN s.__time >= TIMESTAMP '2026-01-31 18:30:00' AND s.__time < TIMESTAMP '2026-02-18 18:30:00' THEN 'Feb 2026 MTD 18' ELSE 'NA' END AS doi, CASE WHEN tr.src_id IS NOT NULL AND tr.dest_id IS NOT NULL THEN 'Target SDs' ELSE 'non-Target SDs' END AS target_route -- , -- CASE -- WHEN ev.is_clicked = 1 THEN 'Card Interacted sessions' -- WHEN ev.is_viewed = 1 THEN 'Viewed but not interacted sessions' -- ELSE 'Regular session' -- END AS section_interaction, -- CASE WHEN ev.is_contextual = 1 THEN 'contextual_filtered_sessions' ELSE 'non-contextual_filtered_sessions' END AS contextual_filter_interaction FROM "user_interaction"."search_route_details" s INNER JOIN target_routes tr ON s.src_id = tr.src_id AND s.dest_id = tr.dest_id /* Only for the target routes */ -- LEFT JOIN target_routes tr ON s.src_id = tr.src_id AND s.dest_id = tr.dest_id /* All routes with identifier for the target routes */ LEFT JOIN "lis"."config_locations" rm ON rm.id = s.src_id WHERE s.__time >= TIMESTAMP '2025-08-31 18:30:00' AND s.__time < TIMESTAMP '2025-12-31 18:30:00' AND s.channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') AND s.country = 'IND' AND s.status = 200 ), confirm_deduped AS ( SELECT mri_session_id, route_id, tin, MAX(rb_user_id) as rb_user_id FROM "user_interaction"."confirm_order_details" WHERE __time >= TIMESTAMP '2025-08-31 18:30:00' AND __time < TIMESTAMP '2025-12-31 18:30:00' AND status = 200 AND tin IS NOT NULL AND tin NOT IN ('', 'null') GROUP BY 1,2,3 ) SELECT srp.doi, -- '0. Jan 01 to Jan 06' AS doi, -- 'Jan 2026' "period", -- srp.search_day, -- 'Any DBD' search_day, CAST(srp.src_id AS VARCHAR) ||'-'|| CAST(srp.dest_id AS VARCHAR) AS SD_ID, (src.location_name ||'-'|| dest.location_name) AS route, '' round_route, UPPER(srp.user_type) as user_type, -- srp.target_route, CASE WHEN srp.os IS NULL THEN srp.channel ELSE srp.os END AS saleschannel, -- srp.region, /* Aggregates */ COUNT(DISTINCT srp.mri_session_id) AS srpload, COUNT(DISTINCT conf.mri_session_id) AS confirmsession, COUNT(DISTINCT conf.tin) AS tin FROM srp_deduped srp LEFT JOIN "lis"."config_locations" src ON srp.src_id = src.id LEFT JOIN "lis"."config_locations" dest ON srp.dest_id = dest.id LEFT JOIN confirm_deduped conf ON srp.mri_session_id = conf.mri_session_id AND srp.route_id = conf.route_id GROUP BY 1,2,3,4,5,6 ORDER BY 1, 5, 6 DESC, 7 DESC;
